from collections import deque


def desks_after_cut(n, links, cut):
    adj = [[] for _ in range(n)]
    for i, (a, b) in enumerate(links):
        if i != cut:
            adj[a].append(b)
            adj[b].append(a)
    seen = [False] * n
    groups = 0
    for s in range(n):
        if seen[s]:
            continue
        groups += 1
        seen[s] = True
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    queue.append(v)
    return groups

def max_profit_k(prices, k):
    if k == 0 or len(prices) < 2:
        return 0
    buy = [float("-inf")] * (k + 1)
    sell = [0] * (k + 1)
    for p in prices:
        for j in range(1, k + 1):
            buy[j] = max(buy[j], sell[j - 1] - p)
            sell[j] = max(sell[j], buy[j] + p)
    return sell[k]

def widest_gap(levels, m):
    xs = sorted(levels)

    def fits(gap):
        placed, last = 1, xs[0]
        for x in xs[1:]:
            if x - last >= gap:
                placed += 1
                last = x
                if placed == m:
                    return True
        return placed >= m

    lo, hi = 0, xs[-1] - xs[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if fits(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
